class Solution:
    def uniqueSorted(self, codes: List[int]) -> List[int]:
        a, n, i = codes[:], len(codes), 1
        while i < n:
            if a[i] == a[i - 1]:
                for j in range(i, n - 1):
                    a[j] = a[j + 1]
                n -= 1
            else:
                i += 1
        return a[:n]

code.java:
class Solution {
    public int[] uniqueSorted(int[] codes) {
        int[] a = codes.clone();
        int n = a.length, i = 1;
        while (i < n) {
            if (a[i] == a[i - 1]) {
                for (int j = i; j < n - 1; j++) a[j] = a[j + 1];
                n--;
            } else i++;
        }
        return Arrays.copyOf(a, n);
    }
}

