    memcpy(a, codes, codesSize * sizeof(int));
    int n = codesSize, i = 1;
    while (i < n) {
        if (a[i] == a[i - 1]) {
            for (int j = i; j < n - 1; j++) a[j] = a[j + 1];
            n--;
        } else i++;
    }
    *returnSize = n;
    return a;
}

